    author: "赵佶",
    gradeGroup: "词牌 · 宴山亭",
    text: "裁剪冰绡，轻叠数重，淡著胭脂匀注。新样靓妆，艳溢香融，羞杀蕊珠宫女。易得凋零，更多少、无情风雨。愁苦。问院落凄凉，几番春暮。\n凭寄离恨重重，这双燕，何曾会人言语。天遥地远，万水千山，知他故宫何处。怎不思量，除梦里、有时曾去。无据。和梦也、新来不做。",
    excerpt: "裁剪冰绡，轻叠数重",
    translation: "杏花像裁剪好的洁白薄绸，轻轻叠成几层，又淡淡地抹上胭脂。它妆饰新巧，艳丽芳香，连蕊珠宫里的仙女见了也自愧不如。可这样美的花偏偏容易凋谢，更禁不起多少无情的风雨。愁苦之中，我问这凄凉的院落：春天已经过去几回了？\n我想托燕子捎去重重离恨，可这双燕又怎么会懂得人话。天遥地远，隔着万水千山，谁知故国的宫殿如今在哪里。怎能不思念，只是除了梦里，有时还能回去一趟。如今连这点凭据也没有了——连梦，近来也不肯做了。",
