    gradeGroup: "词牌 · 木兰花",
    text: "绿杨芳草长亭路，年少抛人容易去。楼头残梦五更钟，花底离愁三月雨。\n无情不似多情苦，一寸还成千万缕。天涯地角有穷时，只有相思无尽处。",
