    gradeGroup: "词牌 · 踏莎行",
    text: "碧海无波，瑶台有路。思量便合双飞去。当时轻别意中人，山长水远知何处。\n绮席凝尘，香闺掩雾。红笺小字凭谁附？高楼目尽欲黄昏，梧桐叶上萧萧雨。",
