    gradeGroup: "词牌 · 凤箫吟",
    text: "锁离愁，连绵无际，来时陌上初熏。绣帏人念远，暗垂珠露，泣送征轮。长行长在眼，更重重、远水孤云。但望极楼高，尽日目断王孙。\n销魂。池塘别后，曾行处、绿妒轻裙。恁时携素手，乱花飞絮里，缓步香茵。朱颜空自改，向年年、芳意长新。遍绿野，嬉游醉眼，莫负青春。",
    excerpt: "遍绿野，嬉游醉眼，莫负青春",
    translation: "芳草锁住离愁，连绵无边；来时路上，草香初起。绣帘中的人思念远行的人，暗暗垂下露珠般的泪，哭着送走远行的车轮。车马走远了，仍在眼中，更有重重远水和孤云。只能登上高楼极目远望，整日望到看不见行人。\n伤心啊。池塘一别之后，她走过的地方，绿草都嫉妒她轻软的罗裙。那时牵着她的素手，在乱花飞絮中缓步走在香草地上。如今红颜白白地改变，而芳草年年依旧新绿。让它绿遍原野吧，纵情游乐、醉眼相看，不要辜负了青春。",
    translationSource: "public-domain",
