    gradeGroup: "词牌 · 蝶恋花",
    text: "谁道闲情抛弃久？每到春来，惆怅还依旧。日日花前常病酒，不辞镜里朱颜瘦。\n河畔青芜堤上柳，为问新愁，何事年年有？独立小桥风满袖，平林新月人归后。",
