    text: "帘幕风轻双语燕，午醉醒来，柳絮飞撩乱。心事一春犹未见，余花落尽青苔院。\n百尺朱楼闲倚遍，薄雨浓云，抵死遮人面。消息未知归早晚，斜阳只送平波远。",
