    dynasty: "宋",
    author: "欧阳修",
    gradeGroup: "词牌 · 木兰花",
    text: "尊前拟把归期说，未语春容先惨咽。人生自是有情痴，此恨不关风与月。\n离歌且莫翻新阕，一曲能教肠寸结。直须看尽洛城花，始共春风容易别。",
