    gradeGroup: "词牌 · 青玉案",
    text: "一年春事都来几？早过了、三之二。绿暗红嫣浑可事，绿杨庭院，暖风帘幕，有个人憔悴。\n买花载酒长安市，又争似、家山见桃李。不枉东风吹客泪，相思难表，梦魂无据，惟有归来是。",
