    translation: "山顶云飞，江边日落，满眼烟波，我倚着栏杆站了很久。望出去关山河川一片萧索，千里清秋，怎忍心一直看下去。遥远的京城，那位盈盈的佳人，别后连书信也难得相通。失群的孤雁没有凭据，缓缓飞下汀洲，我的思念悠悠无尽。\n暗自回想当初，有多少幽会欢聚，哪里知道聚散难以预期，反而变成云雨般的愁恨。想追寻旧游而不可得。每次登山临水，都惹起平生心事，一场黯然消魂，整天说不出一句话，只好走下高楼。",
