    gradeGroup: "词牌 · 千秋岁引",
    text: "别馆寒砧，孤城画角，一派秋声入寥廓。东归燕从海上去，南来雁向沙头落。楚台风，庾楼月，宛如昨。\n无奈被些名利缚，无奈被他情担阁，可惜风流总闲却。当初谩留华表语，而今误我秦楼约。梦阑时，酒醒后，思量着。",
    excerpt: "无奈被些名利缚，无奈被他情担阁",
    translation: "别馆里的寒砧声，孤城上的画角声，一派秋声散入空阔的天空。东归的燕子从海上飞去，南来的大雁落在沙头。楚王的兰台之风、庾亮的南楼之月，宛然如昨。\n无奈被那点名利缠住，无奈被那点人情耽搁，可惜风流都白白闲却了。当初白白留下华表上的话，如今又误了我秦楼的约会。梦醒的时候，酒醒以后，反复思量着。",
