    gradeGroup: "词牌 · 木兰花",
    text: "秋千院落重帘暮，彩笔闲来题绣户。墙头丹杏雨余花，门外绿杨风后絮。\n朝云信断知何处？应作襄王春梦去。紫骝认得旧游踪，嘶过画桥东畔路。",
