    gradeGroup: "词牌 · 木兰花",
    text: "小颦若解愁春暮，一笑留春春也住。晚红初减谢池花，新翠已遮隋堤树。\n谁知错管春残事，到处登临曾费泪。此时金盏直须深，看尽落花能几醉？",
