    gradeGroup: "词牌 · 阮郎归",
    text: "天边金掌露成霜，云随雁字长。绿杯红袖趁重阳，人情似故乡。\n兰佩紫，菊簪黄，殷勤理旧狂。欲将沉醉换悲凉，清歌莫断肠。",
