    author: "晏几道",
    gradeGroup: "词牌 · 虞美人",
    text: "曲阑干外天如水，昨夜还曾倚。初将明月比佳期，长向月圆时候、望人归。\n罗衣着破前香在，旧意谁教改。一春离恨懒调弦，犹有两行闲泪、宝筝前。",
