    gradeGroup: "词牌 · 思远人",
    text: "红叶黄花秋意晚，千里念行客。飞云过尽，归鸿无信，何处寄书得？\n泪弹不尽临窗滴，就砚旋研墨。渐写到别来，此情深处，红笺为无色。",
