    gradeGroup: "词牌 · 青玉案",
    text: "三年枕上吴中路。遣黄耳、随君去。若到松江呼小渡。莫惊鸥鹭，四桥尽是，老子经行处。\n辋川图上看春暮。常记高人右丞句。作个归期天已许。春衫犹是，小蛮针线，曾湿西湖雨。",
    excerpt: "春衫犹是，小蛮针线，曾湿西湖雨",
    translation: "三年梦里都想着回吴中的路。派黄犬随你归去。若到松江叫小渡船，不要惊动鸥鹭；四桥一带，都是我走过的地方。\n在《辋川图》上看春暮的景致，常记得王维那样高人写的句子。定下归期，老天已经答应了。身上的春衫还是小蛮亲手缝的，曾被西湖的雨打湿过。",
