    author: "晁补之",
    gradeGroup: "词牌 · 忆少年",
    text: "无穷官柳，无情画舸，无根行客。南山尚相送，只高城人隔。\n罨画园林溪绀碧，算重来、尽成陈迹。刘郎鬓如此，况桃花颜色。",
    excerpt: "罨画园林溪绀碧，算重来尽成陈迹",
