    gradeGroup: "词牌 · 惜分飞",
    text: "泪湿阑干花著露，愁到眉峰碧聚。此恨平分取，更无言语空相觑。\n断雨残云无意绪，寂寞朝朝暮暮。今夜山深处，断魂分付潮回去。",
