    translation: "小池塘一片新绿，风吹帘动，碎影在斜阳里舞。羡慕那金屋中来去的旧巢燕，羡慕那绕着旧日莓墙的苔花。绣阁里，凤帐深到什么程度？只听得她调理乐器。想说话又停住，怕误了佳音；还没唱就先哽住，愁绪贴近清酒。\n远远想她新妆已就，打开朱门，该在西厢待月。最苦的是梦魂今夜也到不了她身边。问什么时候才能把好消息密告她，送去秦镜、偷换韩香。老天既然让人相见，哪怕只是片刻又何妨！",
