    title: "解连环",
    source: "《宋词三百首》",
    dynasty: "宋",
    author: "周邦彦",
    gradeGroup: "词牌 · 解连环",
    text: "怨怀无托，嗟情人断绝，信音辽邈。纵妙手、能解连环，似风散雨收，雾轻云薄。燕子楼空，暗尘锁、一床弦索。想移根换叶，尽是旧时，手种红药。\n汀洲渐生杜若。料舟依岸曲，人在天角。谩记得、当日音书，把闲语闲言，待总烧却。水驿春回，望寄我、江南梅萼。拚今生、对花对酒，为伊泪落。",
    excerpt: "怨怀无托，嗟情人断绝，信音辽邈",
    translation: "怨怀无处寄托，可叹情人断绝，音信遥远。纵有妙手能解开连环，也像风散雨收、雾轻云薄。燕子楼已空，暗尘锁住一床琴弦。想那草木移根换叶，都是旧时她亲手种的红芍药。\n汀洲上渐渐长出杜若。料想船停泊在弯曲的岸边，人远在天角。白白记得当日的书信，把那些闲言闲语，打算统统烧掉。水边驿站春回，盼望寄我一枝江南梅萼。拼了这辈子，对花对酒，为她落泪。",
