    gradeGroup: "词牌 · 夜游宫",
    text: "叶下斜阳照水，卷轻浪、沉沉千里。桥上酸风射眸子。立多时，看黄昏，灯火市。\n古屋寒窗底，听几片、井桐飞坠。不恋单衾再三起。有谁知，为萧娘，书一纸。",
