    author: "周邦彦",
    gradeGroup: "词牌 · 点绛唇",
    text: "辽鹤归来，故乡多少伤心地。寸书不寄，鱼浪空千里。\n凭仗桃根，说与凄凉意。愁无际，旧时衣袂，犹有东门泪。",
    excerpt: "辽鹤归来，故乡多少伤心地",
    translation: "辽鹤归来，故乡有多少伤心的旧地。一寸书信也不寄，鱼浪白白千里。\n只能依靠桃根，替我诉说凄凉之意。愁绪无边，旧时的衣袖上，还有东门洒下的泪。",
