    author: "贺铸",
    gradeGroup: "词牌 · 天门谣",
    text: "牛渚天门险，限南北、七雄豪占。清雾敛，与闲人登览。\n待月上潮平波滟滟，塞管轻吹新阿滥。风满槛，历历数、西州更点。",
    excerpt: "牛渚天门险，限南北、七雄豪占",
    translation: "牛渚天门形势险要，隔开南北，七国豪杰都曾占据。清雾收敛，让闲人登临观赏。\n等到月出潮平，波光滟滟，塞管轻吹新曲《阿滥堆》。风满栏杆，清晰地数着西州的更点。",
