    gradeGroup: "词牌 · 点绛唇",
    text: "新月娟娟，夜寒江静山衔斗。起来搔首，梅影横窗瘦。\n好个霜天，闲却传杯手。君知否？乱鸦啼后，归兴浓于酒。",
