    gradeGroup: "词牌 · 鹧鸪天",
    text: "一点残红欲尽时，乍凉秋气满屏帏。梧桐叶上三更雨，叶叶声声是别离。\n调宝瑟，拨金猊。那时同唱鹧鸪词。如今风雨西楼夜，不听清歌也泪垂。",
    excerpt: "梧桐叶上三更雨，叶叶声声是别离",
