    author: "姜夔",
    gradeGroup: "词牌 · 点绛唇",
    text: "燕雁无心，太湖西畔随云去。数峰清苦，商略黄昏雨。\n第四桥边，拟共天随住。今何许？凭阑怀古，残柳参差舞。",
