    author: "姜夔",
    gradeGroup: "词牌 · 鹧鸪天",
    text: "肥水东流无尽期，当初不合种相思。梦中未比丹青见，暗里忽惊山鸟啼。\n春未绿，鬓先丝。人间别久不成悲。谁教岁岁红莲夜，两处沉吟各自知。",
    excerpt: "春未绿，鬓先丝。人间别久不成悲",
    translation: "肥水向东流去没有尽期，当初不该种下相思。梦里相见还不如画像分明，暗中忽然被山鸟啼声惊醒。\n春草还没绿，两鬓先白了。人间离别久了也就悲哀不起来。是谁让年年元宵灯夜，两人在两地各自沉吟，只有自己知道。",
