    author: "姜夔",
    gradeGroup: "词牌 · 淡黄柳",
    text: "空城晓角，吹入垂杨陌。马上单衣寒恻恻。看尽鹅黄嫩绿，都是江南旧相识。\n正岑寂，明朝又寒食。强携酒、小桥宅。怕梨花落尽成秋色。燕燕飞来，问春何在，唯有池塘自碧。",
    excerpt: "空城晓角，吹入垂杨陌",
    translation: "空城清晨的号角声，吹进垂杨覆盖的街路。马上单衣，寒意恻恻。看尽鹅黄嫩绿，都是江南旧相识。\n正是岑寂，明天又是寒食。勉强带着酒，到她小桥边的住处。怕梨花落尽，就成了秋色。燕子飞来，问春天在哪里——只有池塘自碧。",
    translationSource: "public-domain",
