    author: "姜夔",
    gradeGroup: "词牌 · 暗香",
    text: "旧时月色，算几番照我，梅边吹笛？唤起玉人，不管清寒与攀摘。何逊而今渐老，都忘却、春风词笔。但怪得、竹外疏花，香冷入瑶席。\n江国，正寂寂。叹寄与路遥，夜雪初积。翠尊易泣，红萼无言耿相忆。长记曾携手处，千树压、西湖寒碧。又片片、吹尽也，几时见得？",
    excerpt: "何逊而今渐老，都忘却、春风词笔",
    translation: "旧时的月色，算来几次照着我，在梅边吹笛？唤起玉人，不管清寒也要攀折。何逊如今渐渐老了，都忘了春风的词笔。只怪竹外那几枝疏花，冷香飘入瑶席。\n江南水乡，正是寂寂。可叹路远难寄，夜雪初积。翠杯容易惹泪，红萼无言，耿耿相忆。常记得曾携手的地方，千树梅花压着西湖的寒碧。又一片片吹尽了，什么时候才能再见？",
