    translation: "寻寻觅觅，冷冷清清，凄凄惨惨戚戚。天气乍暖还寒的时候，最难调养。三杯两盏淡酒，怎么抵得住晚来的急风？大雁飞过，正伤心——却还是旧时相识。\n满地黄花堆积，憔悴得如今还有谁来摘？守在窗边，独自怎么熬到天黑？梧桐上又下着细雨，到黄昏点点滴滴。这般情景，一个「愁」字怎么能说得尽！",
