    translation: "庭院萧条，又是斜风细雨，重门该关上了。宠柳娇花，寒食将近，种种恼人的天气。险韵的诗写成，扶头的酒醒来，另有一番闲滋味。征鸿过尽，万千心事难以寄去。\n楼上几日春寒，四面垂帘，玉栏杆也懒得去倚。被子冷了、香气消了，新梦醒来，不许愁人不起身。清露在晨光里流，新桐刚抽芽，有多少游春的意兴！太阳升高、雾气收敛，再看看今天晴不晴？",
