/* 索引：按 id 查、按词牌查 */
(function () {
  window.SONGCI_ALL = window.POEMS_SONGCI;
  window.getSongciById = function (id) {
    return window.POEMS_SONGCI.filter(function (p) { return p.id === id; })[0] || null;
  };
  window.getSongciGroups = function () {
    var groups = [];
    window.POEMS_SONGCI.forEach(function (p) {
      var g = p.gradeGroup || "其他";
      var hit = groups.filter(function (it) { return it.name === g; })[0];
      if (!hit) { hit = { name: g, items: [] }; groups.push(hit); }
      hit.items.push(p);
    });
    return groups;
  };
})();
